  <div class="page">
    <div class="user-manage__table-wrap">
      <!-- 表格 -->
      <div class="dashboard-overview__order-panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>用户管理</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" row-key="date" :data="pagedData" style="width: 100%">
            <el-table-column prop="username" label="用户"/>
            <el-table-column prop="nickname" label="昵称" width="180" />
            <el-table-column prop="level" label="等级" />
            <el-table-column prop="points" label="积分" width="180" />
            <el-table-column prop="totalprice" label="累计消费" width="180" />
            <el-table-column prop="goodnum" label="订单数"/>
            <el-table-column prop="tag" label="状态" width="100" >
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="创建时间" />
            <el-table-column label="操作" width="120">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '封禁' ? 'success' : 'danger'"
                  @click="handleToggleBan(scope.row.username)"
                >
                  {{ scope.row.tag === '封禁' ? '解封' : '封禁' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <!-- 装分页跟总人数统计盒子 -->
      <div class="user-manage__pagination-wrap">
        <!-- 总人数统计 -->
        <div class="peoplenum">
          <h3>总人数统计</h3>
          <p>当前共 {{ tableData.length }} 人</p>
        </div>
         <!-- 分页 -->
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
        
      </div> 
      
    </div>
  </div>

