<script setup>
import { ref, computed } from 'vue'

// 分页状态
const currentPage = ref(1)
const pageSize = ref(6)
// 当前页展示的数据
const pagedData = computed(() => {
  // currentPage.value：当前页码（从 1 开始）
  // pageSize.value：每页显示的条数（这里是 6）
  // start：当前页第一条数据在完整数据数组里的【起始下标】
  // 计算公式：(当前页 - 1) × 每页条数
  // 第 1 页 → (1-1)*6 = 0，取 slice(0, 6)，即前 6 条
  // 第 2 页 → (2-1)*6 = 6，取 slice(6, 12)，即第 7~12 条
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})
// 状态对应的 el-tag 颜色
const tagType = (tag) => {
  const map = {
    '待验证': 'primary',
    '正常': 'success',
    '封禁': 'danger',
  }
  // 如果 map 中没有对应的 tag，返回 info 颜色
  return map[tag] || 'info'
}

// 封禁 / 解封
const handleToggleBan = (username) => {
  const row = tableData.value.find((item) => item.username === username)
  if (!row) return
  row.tag = row.tag === '封禁' ? '正常' : '封禁'
}

